                section.append(f"{' ' * 78}")

    section.append('+==============================================================================+')
    return section

def get_final_brief(total_vulns_found: int, remediations: Dict[str, Any],
    ignored: Dict[str, Any], total_ignored: int, kwargs: Optional[Dict[str,
    Any]]=None) ->str:
    from safety.util import is_using_api_key
    if not is_using_api_key():
        if total_vulns_found > 0:
            return f"Found {total_vulns_found} vulnerabilities"
        else:
            return "No vulnerabilities found"

    if total_vulns_found == 0:
        if total_ignored == 0:
            return "No vulnerabilities found"
        else:
            return f"No vulnerabilities found. Found {total_ignored} vulnerabilities that were ignored."

    if total_ignored == 0:
        return f"Found {total_vulns_found} vulnerabilities"
    else:
        return f"Found {total_vulns_found} vulnerabilities. Found {total_ignored} vulnerabilities that were ignored."

def format_long_text(text: str, color: str='', columns: int=
    get_terminal_size().columns, start_line_decorator: str=' ',
    end_line_decorator: str=' ', max_lines: Optional[int]=None, styling:
    Optional[Dict[str, Any]]=None, indent: str='', sub_indent: str='') ->str:
    if not styling:
        styling = {}

    if color:
        text = click.style(text, fg=color)

    wrapped_text = textwrap.fill(text, width=columns - len(indent) - len(sub_indent) - 2, initial_indent=indent, subsequent_indent=sub_indent)

    if max_lines:
        lines = wrapped_text.split('\n')
        if len(lines) > max_lines:
            lines = lines[:max_lines]
            wrapped_text = '\n'.join(lines) + '...'

    return wrapped_text

def get_printable_list_of_scanned_items(scanning_target: str) ->Tuple[List[
    Dict[str, Any]], List[str]]:
    ctx = SafetyContext()
    items = []
    names = []

    if scanning_target == 'environment':
        if not ctx.packages:
            items.append([{'styled': False, 'value': 'No locations found in the environment'}])
            names.append('No locations found in the environment')
        else:
            for item in ctx.packages:
                items.append([{'styled': False, 'value': item.name}])
                names.append(item.name)
    elif scanning_target == 'file':
        if hasattr(ctx, 'params') and 'file' in ctx.params:
            file_path = ctx.params['file'].name
            items.append([{'styled': False, 'value': f'-> {file_path}'}])
            names.append(file_path)
        else:
            items.append([{'styled': False, 'value': 'No file found'}])
            names.append('No file found')
    elif scanning_target == 'files':
        if hasattr(ctx, 'params') and 'files' in ctx.params:
            for file_obj in ctx.params['files']:
                file_path = file_obj.name
                items.append([{'styled': False, 'value': f'-> {file_path}'}])
                names.append(file_path)
        else:
            items.append([{'styled': False, 'value': 'No files found'}])
            names.append('No files found')
    elif scanning_target == 'stdin':
        if not ctx.packages:
            items.append([{'styled': False, 'value': 'No found packages in stdin'}])
            names.append('No found packages in stdin')
        else:
            for item in ctx.packages:
                items.append([{'styled': False, 'value': item.name}])
                names.append(item.name)

    return (items, names)

