def build_using_sentence(account: Optional[str], key: Optional[str], db:
    Optional[str]) ->List[Dict[str, Any]]:
    sentence = []

    if account:
        sentence.append({'style': True, 'value': 'Using account: '})
        sentence.append({'style': False, 'value': account})
    elif key:
        sentence.append({'style': True, 'value': 'Using API key: '})
        sentence.append({'style': False, 'value': key})
    elif db:
        sentence.append({'style': True, 'value': 'Using database: '})
        sentence.append({'style': False, 'value': db})
    else:
        sentence.append({'style': True, 'value': 'Using default database'})

    return sentence

def build_scanned_count_sentence(packages: List[Package]) ->List[Dict[str, Any]
    ]:
    count = len(packages)
    sentence = [
        {'style': True, 'value': 'Scanned '},
        {'style': False, 'value': str(count)},
        {'style': True, 'value': ' packages'}
    ]
    return sentence

def get_report_brief_info(as_dict: bool=False, report_type: int=1, **kwargs:
    Any):
    ctx = SafetyContext()
    packages = ctx.packages
    scanned_items = []

    if packages:
        for pkg in packages:
            scanned_items.append(pkg.name)

    if as_dict:
        return {
            'scanned_items': scanned_items,
            'count': len(scanned_items)
        }

    return scanned_items

def format_unpinned_vulnerabilities(unpinned_packages: Dict[str, List[Any]],
    columns: Optional[int]=None) ->List[str]:
    if not unpinned_packages:
        return []

    if not columns:
        columns = get_terminal_size().columns

    lines = []
    for pkg_name, vulnerabilities in unpinned_packages.items():
        if vulnerabilities:
            lines.append(f"Warning: {pkg_name} has {len(vulnerabilities)} known vulnerabilities.")

    if lines:
        lines.insert(0, "Unpinned packages with vulnerabilities:")
        lines.append("")

    return lines
